function apply(base: SystemCase, copy: Copy): SystemCase {
  return {
    ...base,
    ...copy,
    source: base.source ? { ...base.source, label: copy.sourceLabel ?? base.source.label } : undefined,
    sourceBoundary: copy.sourceBoundary ?? base.sourceBoundary,
  };
}

export function localizedSystemCases(locale: Locale): readonly SystemCase[] {
  if (locale === "en") return systemCases;
  const table = locale === "es" ? es : pt;
  return systemCases.map((system) => apply(system, table[system.slug]));
}

export function findLocalizedSystem(locale: Locale, slug: string) {
  return localizedSystemCases(locale).find((system) => system.slug === slug && system.publicability !== "PRIVATE");
}
